import { MakeLogicType, actions, connect, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'
import { teamLogic } from 'scenes/teamLogic'

import { insightsBulkSetDefaultFiltersCreate } from 'products/product_analytics/frontend/generated/api'
import { InsightBulkSetDefaultFiltersResponseApi } from 'products/product_analytics/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface applyDefaultFiltersLogicValues {
    currentProjectId: number | string // teamLogic
    bulkSetResponse: InsightBulkSetDefaultFiltersResponseApi | null
    bulkSetResponseLoading: boolean
    pendingEnabled: boolean | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface applyDefaultFiltersLogicActions {
    applyToExistingInsights: (enabled: boolean) => {
        enabled: boolean
    }
    applyToExistingInsightsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    applyToExistingInsightsSuccess: (
        bulkSetResponse: InsightBulkSetDefaultFiltersResponseApi,
        payload?: {
            enabled: boolean
        }
    ) => {
        bulkSetResponse: InsightBulkSetDefaultFiltersResponseApi
        payload?: {
            enabled: boolean
        }
    }
}

export type applyDefaultFiltersLogicType = MakeLogicType<
    applyDefaultFiltersLogicValues,
    applyDefaultFiltersLogicActions
>

export const applyDefaultFiltersLogic = kea<applyDefaultFiltersLogicType>([
    path(['scenes', 'settings', 'environment', 'applyDefaultFiltersLogic']),
    connect(() => ({
        values: [teamLogic, ['currentProjectId']],
    })),
    actions({
        applyToExistingInsights: (enabled: boolean) => ({ enabled }),
    }),
    reducers({
        pendingEnabled: [
            null as boolean | null,
            {
                applyToExistingInsights: (_, { enabled }) => enabled,
                applyToExistingInsightsSuccess: () => null,
                applyToExistingInsightsFailure: () => null,
            },
        ],
    }),
    loaders(({ values }) => ({
        bulkSetResponse: [
            null as InsightBulkSetDefaultFiltersResponseApi | null,
            {
                applyToExistingInsights: async ({ enabled }: { enabled: boolean }) => {
                    return await insightsBulkSetDefaultFiltersCreate((values.currentProjectId ?? '').toString(), {
                        enabled,
                    })
                },
            },
        ],
    })),
    listeners(() => ({
        applyToExistingInsightsSuccess: ({ bulkSetResponse, payload }) => {
            if (!bulkSetResponse) {
                return
            }
            const { updated, unsupported, skipped, legacy } = bulkSetResponse
            const direction = payload?.enabled ? 'on' : 'off'
            const noun = updated === 1 ? 'insight' : 'insights'
            const extras = [
                unsupported > 0 ? `${unsupported} with no setting for default filters, like SQL insights` : null,
                skipped > 0 ? `${skipped} you can't edit (an organization admin can apply it to those)` : null,
                legacy > 0 ? `${legacy} saved in an older format (open and save one to convert it)` : null,
            ].filter(Boolean)
            const leftAlone = extras.length > 0 ? ` Left alone: ${extras.join(', ')}.` : ''
            if (updated > 0) {
                lemonToast.success(`Turned default filters ${direction} for ${updated} ${noun}.${leftAlone}`)
            } else {
                const nothing = extras.length > 0 ? 'No insights changed.' : 'No insights needed changing.'
                lemonToast.info(`${nothing}${leftAlone}`)
            }
        },
        applyToExistingInsightsFailure: () => {
            lemonToast.error('Could not update your existing insights. Try again in a moment.')
        },
    })),
])
